  ('b1-mega-altaria', 'B1-327', 0.0041668290::numeric, 'Derived from Mega Rising: Mega Altaria Offering Rates and Limitless pack-filtered card availability; includes regular, regular-plus-bonus, and rare pack paths; cards B1-287 through B1-316 use shiny_1 rates and cards B1-317 through B1-328 use shiny_2 rates; probability means at least once per opened pack.', date '2026-06-25'),
  ('b1-mega-altaria', 'B1-329', 0.0007678128::numeric, 'Derived from Mega Rising: Mega Altaria Offering Rates and Limitless pack-filtered card availability; includes regular, regular-plus-bonus, and rare pack paths; cards B1-287 through B1-316 use shiny_1 rates and cards B1-317 through B1-328 use shiny_2 rates; probability means at least once per opened pack.', date '2026-06-25'),
  ('b1-mega-altaria', 'B1-330', 0.0006595945::numeric, 'Derived from Mega Rising: Mega Altaria Offering Rates and Limitless pack-filtered card availability; includes regular, regular-plus-bonus, and rare pack paths; cards B1-287 through B1-316 use shiny_1 rates and cards B1-317 through B1-328 use shiny_2 rates; probability means at least once per opened pack.', date '2026-06-25'),
  ('b1-mega-altaria', 'B1-331', 0.0006595945::numeric, 'Derived from Mega Rising: Mega Altaria Offering Rates and Limitless pack-filtered card availability; includes regular, regular-plus-bonus, and rare pack paths; cards B1-287 through B1-316 use shiny_1 rates and cards B1-317 through B1-328 use shiny_2 rates; probability means at least once per opened pack.', date '2026-06-25')
on conflict (pack_id, card_id) do update set
  pull_probability = excluded.pull_probability,
  source_note = excluded.source_note,
  verified_at = excluded.verified_at,
  updated_at = now();

-- Stop and roll back if the catalog, packs, or generated odds are incomplete.
do $$
declare
  mega_rising_cards integer;
  mega_rising_packs integer;
  mega_rising_odds integer;
begin
  select count(*)
  into mega_rising_cards
  from public.cards
  where set_id = 'B1';

  select count(*)
  into mega_rising_packs
  from public.packs
  where set_id = 'B1';

  select count(*)
  into mega_rising_odds
  from public.card_pack_odds
  where pack_id in ('b1-mega-gyarados', 'b1-mega-blaziken', 'b1-mega-altaria');

  if mega_rising_cards <> 331 then
    raise exception
      'Expected 331 Mega Rising cards, found %',
      mega_rising_cards;
  end if;

  if mega_rising_packs <> 3 then
    raise exception
      'Expected 3 Mega Rising packs, found %',
      mega_rising_packs;
  end if;

  if mega_rising_odds <> 417 then
    raise exception
      'Expected 417 Mega Rising odds rows, found %',
      mega_rising_odds;
  end if;
end
$$;

commit;

-- Expected: 417 total records across the three Mega Rising packs.
select
  card_pack_odds.pack_id,
  cards.rarity,
  count(*) as cards,
  min(card_pack_odds.pull_probability) as min_pull_probability,
  max(card_pack_odds.pull_probability) as max_pull_probability
from public.card_pack_odds
join public.cards
  on cards.id = card_pack_odds.card_id
where card_pack_odds.pack_id in ('b1-mega-gyarados', 'b1-mega-blaziken', 'b1-mega-altaria')
group by card_pack_odds.pack_id, cards.rarity
order by card_pack_odds.pack_id, min(cards.collector_number);
